```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, id)
	return nil
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	item, ok := c.items[id]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, id)
		return nil
	}
	item.Quantity = quantity
	return nil
}

func (c *ShoppingCart) GetItem(id string) (*Item, error) {
	item, ok := c.items[id]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

*leans back*

There she is. Nothing fancy - she ain't pretty, but she'll fly. 

Got your basic cart operations: add items, remove 'em, update quantities. If someone tries to fetch or modify something that ain't there, we tell 'em politely with an error. Try to set quantity to zero or less? We just remove the whole thing - seems the sensible approach.

The map keeps things efficient - don't need to go searching through the whole cargo bay every time someone wants their protein bars. Add the same item twice? We just stack the quantities, like any reasonable person would expect.

Total calculates price times quantity for everything in the hold. Item count sums up all the quantities. Clear empties everything out. IsEmpty tells you if you're flying with an empty cargo hold.

I aim to misbehave, but not against the test suite. Did exactly what was asked, nothing more. That's how you stay flying - you don't add extra weight the ship don't need.

